"""OpenLayers viewer with user-requested XYZ backgrounds and viewport footprints."""
import json
from pathlib import Path
from web_maps import map_data

def write_openlayers_map(plan,path):
    data=json.dumps(map_data(plan),allow_nan=False).replace('<','\\u003c').replace('>','\\u003e').replace('&','\\u0026')
    Path(path).write_text(TEMPLATE.replace('__DATA__',data),encoding='utf-8')

TEMPLATE=r'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Site Planning | OpenLayers</title>
<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/ol@10.11.0/ol.css">
<style>*{box-sizing:border-box}body{margin:0;font:14px system-ui;color:#1b2c43}header{padding:15px 22px;background:#192c45;color:white}h1{margin:0;font-size:21px}main{display:grid;grid-template-columns:310px 1fr;height:calc(100vh - 74px)}aside{padding:16px;overflow:auto}#map{height:100%;min-width:0;background:#e9edf2}select,button{font:inherit;padding:8px;width:100%;margin:6px 0}label{display:block;margin:10px 0}section{border-top:1px solid #ddd;padding-top:12px;margin-top:14px}.small{font-size:12px;line-height:1.5}#status{background:#fff1cb;padding:10px}#info{white-space:pre-wrap;overflow-wrap:anywhere}a{color:#2362ab}.ol-attribution{font-size:11px}.ol-attribution ul{max-width:70vw}</style></head><body><header><h1>Site planning — OpenLayers map</h1><div id="subtitle"></div></header><main><aside>
<strong>Background map</strong><select id="base"><option value="satellite">Google Satellite</option><option value="road">Google Road</option><option value="osm">OpenStreetMap</option></select>
<div class="small">Uses the Google XYZ URLs supplied for this application. Online backgrounds need internet access. Provider access and use conditions apply.</div>
<p id="previewNote" class="small"></p><section><strong>Planning layers</strong><div id="layers"></div></section><div id="status" class="small">Loading OpenLayers…</div>
<section><strong>Selected feature</strong><div id="info" class="small">Click a site, grid or building.</div></section><section><strong>Proposed sites</strong><div id="sites"></div></section>
<section class="small"><a href="planning_map.html">Offline map</a> · <a href="planning_web_map.html">Google API / OSM viewer</a><p><a href="planning_google_earth.kmz" download>Google Earth KMZ preview</a></p><p><a href="building_footprints_used.geojson" download>Full indexed footprint GeoJSON</a></p>Imagery and open footprints support desktop review. Structural suitability, survey accuracy and RF coverage require separate validation.</section></aside><div id="map"></div></main>
<script src="https://cdn.jsdelivr.net/npm/ol@10.11.0/dist/ol.js"></script><script>
const D=__DATA__;const $=id=>document.getElementById(id);
if(!window.ol){$('status').textContent='OpenLayers could not load. Check internet/proxy or open the offline map.';}else{
var wms_layers = [];
var lyr_GoogleRoad_0 = new ol.layer.Tile({title:'Google Road',type:'base',opacity:1,visible:false,source:new ol.source.XYZ({attributions:'Map data © <a href="https://www.google.com/permissions/geoguidelines/">Google</a>',url:'https://mt1.google.com/vt/lyrs=m&x={x}&y={y}&z={z}',maxZoom:20})});
var lyr_GoogleSatellite_1 = new ol.layer.Tile({title:'Google Satellite',type:'base',opacity:1,visible:true,source:new ol.source.XYZ({attributions:'Imagery © <a href="https://www.google.com/permissions/geoguidelines/">Google</a>',url:'https://mt1.google.com/vt/lyrs=s&x={x}&y={y}&z={z}',maxZoom:20})});
var lyr_OpenStreetMap_2=new ol.layer.Tile({title:'OpenStreetMap',type:'base',visible:false,source:new ol.source.OSM()});
const bases={road:lyr_GoogleRoad_0,satellite:lyr_GoogleSatellite_1,osm:lyr_OpenStreetMap_2};const format=new ol.format.GeoJSON();const overlays={};
const names={sites:'Proposed sites',airtel:'Airtel inventory',competitors:'Competitor sites',grids:'Grid KPI categories',no_build:'No-build polygons',buildings:'Building footprints'};
function style(key,f){let color=key==='sites'?'#8c34dc':key==='airtel'?'#1672d3':key==='buildings'?'#deb880':key==='no_build'?'#dc3549':key==='competitors'?'#78909c':({Red:'#eb334b',Amber:'#f1b324',Green:'#22a272',Grey:'#a6aeba'})[f.get('category')]||'#c3c9d3';return new ol.style.Style({stroke:new ol.style.Stroke({color,width:key==='buildings'?1:2}),fill:new ol.style.Fill({color:color+'44'}),image:new ol.style.Circle({radius:key==='sites'?6:key==='grids'?2:3,fill:new ol.style.Fill({color}),stroke:new ol.style.Stroke({color:'#fff',width:1})})})}
for(const key of ['grids','no_build','buildings','competitors','airtel','sites']){const source=new ol.source.Vector({features:format.readFeatures(D.layers[key],{featureProjection:'EPSG:3857'})});overlays[key]=new ol.layer.Vector({source,visible:!['grids','competitors'].includes(key),style:f=>style(key,f)});const label=document.createElement('label');const check=document.createElement('input');check.type='checkbox';check.checked=overlays[key].getVisible();check.onchange=()=>{overlays[key].setVisible(check.checked);if(key==='buildings')updateBuildings();else updatePlanning()};label.append(check,' '+names[key]);$('layers').appendChild(label)}
$('previewNote').textContent=D.summary.map_preview_limits?'Static preview: up to 500 sites and 5,000 grids/inventory records. Full results are in CSV/GeoJSON. Live viewport requests replace these previews while the application remains open.':'';
const map=new ol.Map({target:'map',layers:[lyr_GoogleRoad_0,lyr_GoogleSatellite_1,lyr_OpenStreetMap_2,...Object.values(overlays)],view:new ol.View({center:ol.proj.fromLonLat([20,0]),zoom:4}),controls:ol.control.defaults.defaults({attributionOptions:{collapsible:false}})});
$('base').onchange=()=>{for(const [key,layer] of Object.entries(bases))layer.setVisible(key===$('base').value)};
let tileFailed=false;for(const layer of Object.values(bases))layer.getSource().on('tileloaderror',()=>{if(!tileFailed){tileFailed=true;$('status').textContent='Background tiles failed. Try OpenStreetMap or Google API viewer; planning overlays remain available.'}});
let controller=null,requestId=0;
async function updateBuildings(){if(!overlays.buildings.getVisible())return;const zoom=map.getView().getZoom();if(zoom<13){$('status').textContent='Zoom to level 13 or closer for viewport building queries. Embedded preview remains visible.';return}const extent=ol.proj.transformExtent(map.getView().calculateExtent(map.getSize()),'EPSG:3857','EPSG:4326');if(extent[0]<-180||extent[2]>180||extent[2]-extent[0]>1||extent[3]-extent[1]>1){$('status').textContent='Zoom in further for local building queries.';return}if(controller)controller.abort();controller=new AbortController();const id=++requestId;try{const response=await fetch('/api/buildings?bbox='+encodeURIComponent(extent.join(',')),{signal:controller.signal});if(!response.ok)throw Error('Index endpoint unavailable');const payload=await response.json();if(id!==requestId)return;const source=overlays.buildings.getSource();source.clear();source.addFeatures(format.readFeatures(payload,{featureProjection:'EPSG:3857'}));$('status').textContent=payload.features.length.toLocaleString()+' viewport footprints from '+payload.total_indexed.toLocaleString()+' indexed.'+(payload.truncated?' View capped at 5,000; zoom in for more detail.':'')+' Planning uses all nearby indexed footprints.'}catch(e){if(e.name!=='AbortError')$('status').textContent='Showing embedded building preview ('+D.layers.buildings.features.length.toLocaleString()+' of '+D.building_total.toLocaleString()+'). Open this output from the running desktop app for live disk-index queries.'}}
let planningRequest=0;
async function updatePlanning(){if(!D.summary.database_path)return;const id=++planningRequest;let bbox=ol.proj.transformExtent(map.getView().calculateExtent(map.getSize()),'EPSG:3857','EPSG:4326');bbox=[Math.max(-180,bbox[0]),Math.max(-90,bbox[1]),Math.min(180,bbox[2]),Math.min(90,bbox[3])];for(const key of ['sites','grids','airtel','competitors','no_build']){if(!overlays[key].getVisible())continue;try{const response=await fetch('/api/planning?layer='+key+'&bbox='+encodeURIComponent(bbox.join(',')));if(!response.ok)continue;const data=await response.json();if(id!==planningRequest)return;const source=overlays[key].getSource();source.clear();source.addFeatures(format.readFeatures(data,{featureProjection:'EPSG:3857'}));if(data.truncated)$('previewNote').textContent='Viewport layer capped at 5,000 features. Zoom in for details. Full output files include all planned sites.'}catch(e){/* Embedded preview remains usable when the temporary session has closed. */}}}
map.on('moveend',()=>{updateBuildings();updatePlanning()});map.on('singleclick',event=>{let feature=map.forEachFeatureAtPixel(event.pixel,f=>f);if(!feature)return;const properties={...feature.getProperties()};delete properties.geometry;$('info').textContent=Object.entries(properties).map(([k,v])=>k+': '+v).join('\n')});
for(const f of D.layers.sites.features){const button=document.createElement('button');button.textContent=f.properties.rank+'. '+f.properties.candidate_id;button.onclick=()=>{map.getView().animate({center:ol.proj.fromLonLat(f.geometry.coordinates),zoom:17,duration:400});$('info').textContent=Object.entries(f.properties).map(([k,v])=>k+': '+v).join('\n')};$('sites').appendChild(button)}
const fit=overlays.sites.getSource().getFeatures().length?overlays.sites:overlays.grids;if(fit.getSource().getFeatures().length)map.getView().fit(fit.getSource().getExtent(),{padding:[40,40,40,40],maxZoom:16});
$('subtitle').textContent=D.summary.country+' · '+D.summary.grid_period+' · '+D.summary.mode;
$('status').textContent=D.building_total.toLocaleString()+' footprints indexed/loaded. Zoom in to query the current viewport.';
}
</script></body></html>'''
